//=============================================================================
// Flattened Decision Tree FSM: record_ports
// Generated using Enable-based Methodology with WEN/EN Signals
// Date: Fri Oct  2 01:48:12 2026
// 
// This implementation uses:
// - Flattened decision tree approach
// - Enable-based logic with assign statements
// - Write Enable (WEN) and Enable (EN) signals for each LHS
// - Flat Boolean expressions from DT traversal
//=============================================================================

typedef struct packed {
    logic flag;
    logic signed [4:0] data;
} fsmgen_m12_record_ports__frame__fsmgen_t; // frame

module record_ports (
  input  wire clk,
  input  wire rst_n,
  input fsmgen_m12_record_ports__frame__fsmgen_t packet,
  input  wire start,
  output reg  done,
  output fsmgen_m12_record_ports__frame__fsmgen_t result,
  output reg  [4:0] seen
);

  // State encoding
  localparam MAIN_IDLE_0 = 3'd0;
  localparam MAIN_SET_1 = 3'd1;
  localparam MAIN_SET_2 = 3'd2;
  localparam MAIN_SET_3 = 3'd3;
  localparam MAIN_DONE_4 = 3'd4;

  // State registers
  reg [2:0] current_state, next_state;

  // State sequential logic
  always_ff @(posedge clk) begin
    if (!rst_n) begin
      current_state <= MAIN_IDLE_0;
    end else begin
      current_state <= next_state;
    end
  end

  // Internal signal declarations
  reg can_accept;
  fsmgen_m12_record_ports__frame__fsmgen_t held;
  // Internal mux helper registers
  reg done_pulse_delay_pipe;
  fsmgen_m12_record_ports__frame__fsmgen_t held_next;
  fsmgen_m12_record_ports__frame__fsmgen_t result_next;
  reg [4:0] seen_next;
  // Generated enable wires
  wire can_accept_1_en;
  wire done_1_en;
  wire held_packet_en;
  wire main_done_4_done_1_en;
  wire main_done_4_en;
  wire main_done_4_next_state_main_idle_0_en;
  wire main_idle_0_can_accept_1_en;
  wire main_idle_0_en;
  wire main_idle_0_next_state_main_set_1_en;
  wire main_set_1_en;
  wire main_set_1_held_packet_en;
  wire main_set_1_next_state_main_set_2_en;
  wire main_set_2_en;
  wire main_set_2_next_state_main_set_3_en;
  wire main_set_2_result_held_en;
  wire main_set_3_en;
  wire main_set_3_next_state_main_done_4_en;
  wire main_set_3_seen_result_data_en;
  wire next_state_main_done_4_en;
  wire next_state_main_idle_0_en;
  wire next_state_main_set_1_en;
  wire next_state_main_set_2_en;
  wire next_state_main_set_3_en;
  wire result_held_en;
  wire seen_result_data_en;

  // State and DT Enable Conditions
  assign main_done_4_en = current_state == MAIN_DONE_4;
  assign main_idle_0_en = current_state == MAIN_IDLE_0;
  assign main_set_1_en = current_state == MAIN_SET_1;
  assign main_set_2_en = current_state == MAIN_SET_2;
  assign main_set_3_en = current_state == MAIN_SET_3;

  // Unified WEN/EN Signal Generation from Phase 1 Analysis
  // DT-Specific Enable Signals from Unified Analysis


  // === DT: main_done_4 ===
  // done
  assign main_done_4_done_1_en = main_done_4_en;  // done <- 1
  // next_state
  assign main_done_4_next_state_main_idle_0_en = main_done_4_en;  // next_state <- MAIN_IDLE_0


  // === DT: main_idle_0 ===
  // can_accept
  assign main_idle_0_can_accept_1_en = main_idle_0_en;  // can_accept <- 1
  // next_state
  assign main_idle_0_next_state_main_set_1_en = main_idle_0_en & start;  // next_state <- MAIN_SET_1


  // === DT: main_set_1 ===
  // held
  assign main_set_1_held_packet_en = main_set_1_en;  // held <- packet
  // next_state
  assign main_set_1_next_state_main_set_2_en = main_set_1_en;  // next_state <- MAIN_SET_2


  // === DT: main_set_2 ===
  // next_state
  assign main_set_2_next_state_main_set_3_en = main_set_2_en;  // next_state <- MAIN_SET_3
  // result
  assign main_set_2_result_held_en = main_set_2_en;  // result <- held


  // === DT: main_set_3 ===
  // next_state
  assign main_set_3_next_state_main_done_4_en = main_set_3_en;  // next_state <- MAIN_DONE_4
  // seen
  assign main_set_3_seen_result_data_en = main_set_3_en;  // seen <- result.data

  // LHS-Level Enable Signals from Unified Analysis

  // LHS-level enables for: can_accept
  assign can_accept_1_en = main_idle_0_can_accept_1_en;

  // LHS-level enables for: done
  assign done_1_en = main_done_4_done_1_en;

  // LHS-level enables for: held
  assign held_packet_en = main_set_1_held_packet_en;

  // LHS-level enables for: next_state
  assign next_state_main_done_4_en = main_set_3_next_state_main_done_4_en;
  assign next_state_main_idle_0_en = main_done_4_next_state_main_idle_0_en;
  assign next_state_main_set_1_en = main_idle_0_next_state_main_set_1_en;
  assign next_state_main_set_2_en = main_set_1_next_state_main_set_2_en;
  assign next_state_main_set_3_en = main_set_2_next_state_main_set_3_en;

  // LHS-level enables for: result
  assign result_held_en = main_set_2_result_held_en;

  // LHS-level enables for: seen
  assign seen_result_data_en = main_set_3_seen_result_data_en;

  // Unified Multiplexer Logic from Phase 1 Analysis

  // Unified Multiplexer for LHS: can_accept
  // Unified combinational mux for: can_accept
  always_comb begin
    can_accept = 1'b0;  // Default value
    if (can_accept_1_en) begin
      can_accept = 1;
    end
  end

  // Unified Multiplexer for LHS: done
  // Delayed pulse logic for: done (<1, exact Q+1)
  always_ff @(posedge clk) begin
    if (!rst_n) begin
      done <= 1'b0;
      done_pulse_delay_pipe <= 1'b0;
    end else begin
      done <= 1'b0;
      if (done_pulse_delay_pipe) begin
        done <= 1'b1;
      end
      done_pulse_delay_pipe <= done_1_en;
    end
  end

  // Unified Multiplexer for LHS: held
  // Unified flop with mux for: held (register_out assignment)
  always_comb begin
    held_next = held;  // Default value
    if (held_packet_en) begin
      held_next = packet;
    end
  end
  always_ff @(posedge clk) begin
    if (!rst_n) begin
      held <= 6'h00;
    end else begin
      held <= held_next;
    end
  end

  // Unified Multiplexer for LHS: next_state
  // Unified combinational mux for: next_state
  always_comb begin
    next_state = current_state;  // Default value
    if (next_state_main_done_4_en) begin
      next_state = MAIN_DONE_4;
    end
    if (next_state_main_idle_0_en) begin
      next_state = MAIN_IDLE_0;
    end
    if (next_state_main_set_1_en) begin
      next_state = MAIN_SET_1;
    end
    if (next_state_main_set_2_en) begin
      next_state = MAIN_SET_2;
    end
    if (next_state_main_set_3_en) begin
      next_state = MAIN_SET_3;
    end
  end

  // Unified Multiplexer for LHS: result
  // Unified flop with mux for: result (register_out assignment)
  always_comb begin
    result_next = result;  // Default value
    if (result_held_en) begin
      result_next = held;
    end
  end
  always_ff @(posedge clk) begin
    if (!rst_n) begin
      result <= 6'h00;
    end else begin
      result <= result_next;
    end
  end

  // Unified Multiplexer for LHS: seen
  // Unified flop with mux for: seen (register_out assignment)
  always_comb begin
    seen_next = seen;  // Default value
    if (seen_result_data_en) begin
      seen_next = result.data;
    end
  end
  always_ff @(posedge clk) begin
    if (!rst_n) begin
      seen <= 5'h00;
    end else begin
      seen <= seen_next;
    end
  end

  `ifndef SYNTHESIS
  always_comb begin
    assert ($onehot0({next_state_main_done_4_en, next_state_main_idle_0_en, next_state_main_set_1_en, next_state_main_set_2_en, next_state_main_set_3_en})) else $error("selector multi-value conflict: next_state");
  end
  `endif
endmodule

